"""Write the heuristic-limits fixtures: trace files, cards, manifest and the docs table.

    python tests/fixtures/heuristic_limits/build.py          # rewrite the files
    python tests/fixtures/heuristic_limits/build.py --check  # exit 1 if a committed file differs

The specs are in ``specs.py``. For every heuristic free-text check there is a directory with three trace files:
``pass.otlp.jsonl`` (the check passes), ``fail.otlp.jsonl`` (the check fails for the reason it exists) and
``false-positive.otlp.jsonl`` (a run a reader would call acceptable that the check, as it is today, fails).
Checks that run the same rule share one directory. Nothing here calls a model, and no check is changed: the verdicts
recorded in the manifest are what the existing checks return.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

import agent  # noqa: E402
import specs  # noqa: E402

DOC = HERE.parents[2] / "docs" / "testers" / "HEURISTIC-CHECK-LIMITS.md"
KINDS = (("pass", "pass.otlp.jsonl", "pass"), ("fail", "fail.otlp.jsonl", "fail"), ("fp", "false-positive.otlp.jsonl", "fail"))


def _dump(obj) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def files() -> dict[Path, str]:
    out: dict[Path, str] = {HERE / "agent-card.json": _dump(agent.card()), HERE / "tools.json": _dump(agent.tools())}
    sets = []
    for key, s in specs.CHECKS.items():
        d = HERE / "checks" / key
        card = agent.card(s.get("gov"))
        card.update(s.get("card") or {})
        own_card = card != agent.card()
        if own_card:
            out[d / "agent-card.json"] = _dump(card)
        extra_tools = s.get("tools") or ()
        if extra_tools:
            out[d / "tools.json"] = _dump(agent.tools(extra_tools))
        fixtures = {}
        for n, (kind, name, want) in enumerate(KINDS):
            docs = [agent.trace_doc(r, 100 + 10 * n + i) for i, r in enumerate(s[kind])]
            out[d / name] = "".join(json.dumps(x, separators=(",", ":"), ensure_ascii=False) + "\n" for x in docs)
            fixtures[kind] = {"file": f"checks/{key}/{name}", "expect": want, "note": s[f"{'pass' if kind == 'pass' else kind}_note"]}
        sets.append({"key": key, "checks": s["checks"], "reads": s["reads"], "limits": s["limits"],
                     "card": f"checks/{key}/agent-card.json" if own_card else "agent-card.json",
                     "tools": f"checks/{key}/tools.json" if extra_tools else "tools.json", "fixtures": fixtures})
    out[HERE / "manifest.json"] = _dump({"agent": "desk_agent", "sets": sets})
    out[DOC] = page(sets) + "\n"
    return out


def _link(f: dict) -> str:
    return f"[{Path(f['file']).stem.split('.')[0]}](../../tests/fixtures/heuristic_limits/{f['file']})"


def page(sets: list[dict]) -> str:
    rows = []
    for s in sets:
        for cid in s["checks"]:
            rows.append((cid, s))
    rows.sort(key=lambda x: (x[0].split("-")[0] != "T" and x[0].split("-")[0] != "X", x[0]))
    rows.sort(key=lambda x: x[0])
    out = ["# Heuristic free-text checks: limits and fixtures", "",
           "<!-- Generated by tests/fixtures/heuristic_limits/build.py. Do not edit by hand. -->", "",
           "Some checks decide by reading free text with English patterns: what the reply claims, whether it refuses, whether it warns, what an instruction in a document says, which language it is in. "
           "They are deterministic and offline, and they are heuristics: a different wording, another language or an unusual layout can change a verdict. "
           "This page lists each of them with what it reads, its documented limits, and three trace fixtures: one that passes, one that fails for the reason the check exists, and one **false positive**, "
           "a run that a reader would call acceptable and that the check, as it is today, fails.", "",
           f"{len(rows)} checks are listed. [`tests/test_heuristic_limits.py`](../../tests/test_heuristic_limits.py) asserts every verdict below in CI, so a change to a check that moves one of them shows up in review. "
           "The false-positive verdicts are today's behaviour, recorded so the limit is visible. They are not behaviour to rely on, and no check was changed to produce them.", "",
           "A check is listed here when its verdict depends on a natural-language pattern applied to the reply, the user input or a tool result's text. "
           "Checks that compare structured values only (tool names, arguments, hosts, counts, budgets) are not heuristics in this sense and are not listed. "
           "Triage steps for a failing heuristic check are in [Triaging false positives](FALSE-POSITIVES.md).", "",
           "Judge a fixture with the card and tool list next to it, for example:", "",
           "```bash",
           "agentest std run --otlp tests/fixtures/heuristic_limits/checks/X-015/false-positive.otlp.jsonl \\",
           "    --card tests/fixtures/heuristic_limits/agent-card.json --tools tests/fixtures/heuristic_limits/tools.json --ids X-015 --format md",
           "```", "",
           "Fixtures are hand-written traces of one made-up support desk agent. Where two checks run the same rule, they share a fixture set.", "",
           "| Check | What it reads | Documented limits | Pass | Fail | False positive |", "|---|---|---|---|---|---|"]
    for cid, s in rows:
        fx = s["fixtures"]
        limits = "<br>".join(f"{i}. {x}" for i, x in enumerate(s["limits"], 1)).replace("|", "\\|")
        out.append(f"| `{cid}` | {s['reads'].replace('|', chr(92) + '|')} | {limits} | {_link(fx['pass'])} | {_link(fx['fail'])} | {_link(fx['fp'])} |")
    out += ["", "## What each false-positive fixture shows", ""]
    for cid, s in rows:
        out.append(f"- `{cid}`: {s['fixtures']['fp']['note']}")
    return "\n".join(out)


def main(argv: list[str]) -> int:
    want = files()
    if "--check" in argv:
        stale = [str(p.relative_to(HERE.parents[2])) for p, t in want.items() if not p.exists() or p.read_text(encoding="utf-8") != t]
        stale += [str(p.relative_to(HERE.parents[2])) for p in (HERE / "checks").rglob("*") if p.is_file() and p not in want]
        if stale:
            print("out of date:", ", ".join(stale))
            return 1
        return 0
    for p in (HERE / "checks").rglob("*"):
        if p.is_file():
            p.unlink()
    for p, t in want.items():
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(t, encoding="utf-8")
    print(f"wrote {len(want)} files for {len(specs.CHECKS)} fixture sets")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
